package com.marketintel.service;
class LogisticRegressionModel {private final double[] w;private final double lr;LogisticRegressionModel(int n,double lr){w=new double[n+1];this.lr=lr;}void fit(double[][]x,int[]y,int epochs){for(int e=0;e<epochs;e++)for(int i=0;i<x.length;i++){double p=predictProbability(x[i]);double err=y[i]-p;w[0]+=lr*err;for(int j=0;j<x[i].length;j++)w[j+1]+=lr*err*x[i][j];}}double predictProbability(double[]x){double z=w[0];for(int j=0;j<x.length;j++)z+=w[j+1]*x[j];if(z>35)return 1;if(z<-35)return 0;return 1/(1+Math.exp(-z));}int predict(double[]x){return predictProbability(x)>=.5?1:0;}}